if (points.empty()) {
        return std::vector<std::vector<Point2d>>();
    }

    // CGAL typedefs
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    typedef CGAL::Delaunay_triangulation_adaptation_traits_2<DT> AT;
    typedef CGAL::Delaunay_triangulation_caching_degeneracy_removal_policy_2<DT> AP;
    typedef CGAL::Voronoi_diagram_2<DT, AT, AP> VD;

    typedef AT::Site_2 Site_2;
    typedef AT::Point_2 Point_2;
    typedef VD::Vertex_handle Vertex_handle;
    typedef VD::Face_handle Face_handle;
    typedef VD::Halfedge_handle Halfedge_handle;
    typedef VD::Ccb_halfedge_circulator Ccb_halfedge_circulator;

    // Create CGAL points from input
    std::vector<Point_2> cgal_points;
    cgal_points.reserve(points.size());
    for (const Point2d& p : points) {
        cgal_points.emplace_back(p.x(), p.y());
    }

    // Build Delaunay triangulation
    DT dt;
    dt.insert(cgal_points.begin(), cgal_points.end());

    // Create Voronoi diagram
    VD vd(dt);

    // Extract Voronoi cells
    std::vector<std::vector<Point2d>> result;
    result.reserve(vd.number_of_vertices());

    // Iterate through all Voronoi vertices (cells)
    for (VD::Vertex_iterator vit = vd.vertices_begin(); vit != vd.vertices_end(); ++vit) {
        std::vector<Point2d> cell;

        // Get the dual face (corresponding to the input point)
        Face_handle face = vit->dual();
        if (face == Face_handle()) continue;

